func withSuffix(base, suffixes []string) [][]string {
    res := make([][]string, 0, len(suffixes))
    for _, sfx := range suffixes {
        v := make([]string, len(base), len(base)+1)
        copy(v, base)
        res = append(res, append(v, sfx))
    }
    return res
}
